270	    /**
271	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
272	     * offending field is collected so the caller learns exactly which values must be supplied.
273	     *
274	     * @param ownerFieldsDto the submitted owner payload
275	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
276	     *         telephone is missing or blank
277	     */
278	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
279	        List<String> missingFields = new ArrayList<>();
280	        if (isBlank(ownerFieldsDto.getFirstName())) {
281	            missingFields.add("firstName");
282	        }
283	        if (isBlank(ownerFieldsDto.getLastName())) {
284	            missingFields.add("lastName");
285	        }
286	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
287	            missingFields.add("address");
288	        }
289	        if (isBlank(ownerFieldsDto.getCity())) {
290	            missingFields.add("city");
291	        }
292	        if (isBlank(ownerFieldsDto.getTelephone())) {
293	            missingFields.add("telephone");
294	        }
295	        if (!missingFields.isEmpty()) {
296	            throw new MissingOwnerFieldsException(missingFields);
297	        }
298	    }
