304	    /**
305	     * Counts the existing owners who, before this create, already share the given first and last name.
306	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
307	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
308	     * case or spacing still count as the same name.
309	     *
310	     * @param firstName the first name of the owner being created
311	     * @param lastName the last name of the owner being created
312	     * @return the number of existing owners sharing both names (zero when none)
313	     */
314	    private int countNamesakes(String firstName, String lastName) {
315	        String first = normalizeHouseholdField(firstName);
316	        String last = normalizeHouseholdField(lastName);
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
319	                && normalizeHouseholdField(existing.getLastName()).equals(last))
320	            .count();
321	    }
