323	    /**
324	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
325	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
326	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
327	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
328	     * more owners the create is rejected as a conflict.
329	     *
330	     * @param city the city of the owner being created
331	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
332	     */
333	    /**
334	     * Rejects an owner create once the maximum number of owners have already been registered on the
335	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
336	     * which is always a business day (a weekend effective date is rolled forward to the following
337	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
338	     * business day the create is rejected as too many requests. Because a weekend effective date is
339	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
340	     *
341	     * @param businessDay the adjusted business day the owner being created would be registered on
342	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
343	     */
344	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
345	        long ownersOnDay = this.clinicService.findAllOwners().stream()
346	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
347	            .count();
348	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
349	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
350	        }
351	    }
352	
353	    /**
354	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
355	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
356	     * was supplied on the request or defaulted to the server's current date.
357	     *
358	     * @param date the effective registration date (supplied or defaulted)
359	     * @return the same date when it is a weekday, otherwise the following Monday
360	     */
361	    /**
362	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
363	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
364	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
365	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
366	     *
367	     * @return {@code true} when more than the threshold number of owners are already registered on
368	     *         today's business day, otherwise {@code false}
369	     */
370	    private boolean isBulkSignupWarningActive() {
371	        LocalDate today = toBusinessDay(LocalDate.now());
372	        long ownersToday = this.clinicService.findAllOwners().stream()
373	            .filter(existing -> today.equals(existing.getRegistrationDate()))
374	            .count();
375	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
376	    }
377	
378	    private LocalDate toBusinessDay(LocalDate date) {
379	        return switch (date.getDayOfWeek()) {
380	            case SATURDAY -> date.plusDays(2);
381	            case SUNDAY -> date.plusDays(1);
382	            default -> date;
383	        };
384	    }
