386	    private void rejectCityAtCapacity(String city) {
387	        String normalizedCity = normalizeHouseholdField(city);
388	        long ownersInCity = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
390	            .count();
391	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
392	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
393	        }
394	    }
