396	    /**
397	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
398	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
399	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
400	     * of owners already in that city (e.g. 'SYD-SMI-0007').
401	     *
402	     * @param city the owner's city
403	     * @param lastName the owner's last name
404	     * @return the formatted customer code
405	     */
406	    private String generateCustomerCode(String city, String lastName) {
407	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
408	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
409	        String normalizedCity = normalizeHouseholdField(city);
410	        int sequence = (int) this.clinicService.findAllOwners().stream()
411	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
412	            .count() + 1;
413	        return String.format("%s-%s-%04d", city3, last3, sequence);
414	    }
