416	    /**
417	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
418	     * customerCode is the owner's customer code and YY is the last two digits of the
419	     * registrationDate year (e.g. 'SMI-0007-M26').
420	     *
421	     * @param customerCode the owner's customer code
422	     * @param registrationDate the owner's registration date
423	     * @return the formatted membership number
424	     */
425	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
426	        String yy = String.format("%02d", registrationDate.getYear() % 100);
427	        return customerCode + "-M" + yy;
428	    }
