430	    /**
431	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
432	     * country calling code. Australia ('+61') uses 9 national digits and the North American
433	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
434	     * E.164 length (8 to 15 digits overall).
435	     */
436	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
437	        java.util.Map.of("61", 9, "1", 10);
438	
439	    /**
440	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
441	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
442	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
443	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
444	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
445	     * E.164 string is what gets stored and returned.
446	     *
447	     * @param telephone the raw telephone value from the request
448	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
449	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
450	     *         national number has the wrong length for its country code
451	     */
452	    private String normalizeTelephone(String telephone) {
453	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
454	        String e164;
455	        if (cleaned.startsWith("+")) {
456	            e164 = cleaned;
457	        } else {
458	            String national = cleaned;
459	            if (national.startsWith("0")) {
460	                national = national.substring(1);
461	            }
462	            e164 = "+61" + national;
463	        }
464	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
465	            throw new InvalidOwnerFieldsException(List.of("telephone"));
466	        }
467	        validateNationalNumberLength(e164);
468	        return e164;
469	    }
470	
471	    /**
472	     * Rejects an E.164 telephone whose national number does not have the exact length its country
473	     * calling code requires. The digits after the leading '+' are split into the longest matching
474	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
475	     * code is known and the national number's length differs from the required count the telephone is
476	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
477	     *
478	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
479	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
480	     */
481	    private void validateNationalNumberLength(String e164) {
482	        String digits = e164.substring(1);
483	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
484	            String countryCode = digits.substring(0, codeLength);
485	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
486	            if (requiredNationalLength != null) {
487	                int nationalLength = digits.length() - codeLength;
488	                if (nationalLength != requiredNationalLength) {
489	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
490	                }
491	                return;
492	            }
493	        }
494	    }
495	
496	    /**
497	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
498	     * left unset. When a value is present it must be a syntactically valid address; the normalized
499	     * form stored and returned is the value lower-cased.
500	     *
501	     * @param email the raw email value from the request, or {@code null} when none was supplied
502	     * @return the lower-cased email, or {@code null} when no email was supplied
503	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
504	     */
505	    private String normalizeEmail(String email) {
506	        if (email == null || email.isBlank()) {
507	            return null;
508	        }
509	        if (!EMAIL_PATTERN.matcher(email).matches()) {
510	            throw new InvalidOwnerFieldsException(List.of("email"));
511	        }
512	        return email.toLowerCase(Locale.ROOT);
513	    }
514	
515	    /**
516	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
517	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
518	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
519	     * normalized form is what gets stored, returned and used for every address comparison (the
520	     * required-field check, household duplicate detection and the shared household id).
521	     *
522	     * @param address the raw address value from the request, or {@code null}
523	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
524	     */
525	    private String normalizeAddress(String address) {
526	        if (address == null) {
527	            return "";
528	        }
529	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
530	        if (collapsed.isEmpty()) {
531	            return "";
532	        }
533	        String[] tokens = collapsed.split(" ");
534	        for (int i = 0; i < tokens.length; i++) {
535	            switch (tokens[i]) {
536	                case "ST" -> tokens[i] = "STREET";
537	                case "RD" -> tokens[i] = "ROAD";
538	                case "AVE" -> tokens[i] = "AVENUE";
539	                default -> { }
540	            }
541	        }
542	        return String.join(" ", tokens);
543	    }
