545	    /**
546	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
547	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
548	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
549	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
550	     * so two members of one household with different telephones have different keys and are both
551	     * allowed; only an owner whose entire key is identical is a duplicate.
552	     *
553	     * @param owner the owner being created, with its telephone, email and householdId already resolved
554	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
555	     */
556	    private void rejectDuplicateIdentity(Owner owner) {
557	        String identityKey = owner.getIdentityKey();
558	        boolean inUse = this.clinicService.findAllOwners().stream()
559	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
560	        if (inUse) {
561	            throw new DuplicateOwnerIdentityException(identityKey);
562	        }
563	    }
564	
565	    /**
566	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
567	     * last name and a normalized address: last names are compared case-insensitively after whitespace
568	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
569	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
570	     * abbreviation still count as the same household.
571	     * <p>
572	     * When the owner's last name and address already belong to at least one other owner and
573	     * {@code sharesHousehold} is true, every member of the household - the existing owners and this
574	     * joiner - is assigned the same stable {@code householdId}, which is returned on read and forms
575	     * the third component of the {@code identityKey}. When {@code sharesHousehold} is not true, or no
576	     * other owner shares the last name and address, no identifier is assigned. Household membership no
577	     * longer rejects a create on its own; duplicates are detected solely through the identity key.
578	     *
579	     * @param owner the owner being created
580	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
581	     */
582	    /**
583	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
584	     * household member count} for the response.
585	     *
586	     * @param owner the owner to map
587	     * @return the mapped owner DTO
588	     */
589	    private OwnerDto toOwnerDto(Owner owner) {
590	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
591	        return ownerMapper.toOwnerDto(owner);
592	    }
593	
594	    /**
595	     * Counts the members of the given owner's household - the owners that share this owner's
596	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
597	     * is {@code null}) is its own sole member, so the count is one.
598	     *
599	     * @param owner the owner whose household is being sized
600	     * @return the number of owners sharing this owner's household (one when it has no household)
601	     */
602	    private int countHouseholdMembers(Owner owner) {
603	        String householdId = owner.getHouseholdId();
604	        if (householdId == null) {
605	            return 1;
606	        }
607	        return (int) this.clinicService.findAllOwners().stream()
608	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
609	            .count();
610	    }
611	
612	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
613	        String lastName = normalizeHouseholdField(owner.getLastName());
614	        String address = normalizeAddress(owner.getAddress());
615	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
616	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
617	                && normalizeAddress(existing.getAddress()).equals(address))
618	            .toList();
619	        if (housemates.isEmpty()) {
620	            return;
621	        }
622	        if (!Boolean.TRUE.equals(sharesHousehold)) {
623	            return;
624	        }
625	        String householdId = generateHouseholdId(lastName, address);
626	        owner.setHouseholdId(householdId);
627	        for (Owner housemate : housemates) {
628	            if (!householdId.equals(housemate.getHouseholdId())) {
629	                housemate.setHouseholdId(householdId);
630	                this.clinicService.saveOwner(housemate);
631	            }
632	        }
633	    }
634	
635	    /**
636	     * Builds the stable identifier shared by the members of one household. It is derived purely from
637	     * the normalized last name and address, so every owner of a given household deterministically
638	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
639	     * two normalized fields joined by a single space.
640	     *
641	     * @param normalizedLastName the household's last name, already normalized for comparison
642	     * @param normalizedAddress the household's address, already normalized for comparison
643	     * @return the shared household identifier
644	     */
645	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
646	        String key = normalizedLastName + '�' + normalizedAddress;
647	        try {
648	            byte[] digest = MessageDigest.getInstance("SHA-256")
649	                .digest(key.getBytes(StandardCharsets.UTF_8));
650	            StringBuilder hex = new StringBuilder();
651	            for (byte b : digest) {
652	                hex.append(String.format("%02X", b));
653	                if (hex.length() >= 12) {
654	                    break;
655	                }
656	            }
657	            return hex.substring(0, 12);
658	        } catch (NoSuchAlgorithmException e) {
659	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
660	        }
661	    }
662	
663	    /**
664	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
665	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
666	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
667	     * expands common abbreviations.
668	     *
669	     * @param value the raw last name, or {@code null}
670	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
671	     */
672	    private String normalizeHouseholdField(String value) {
673	        if (value == null) {
674	            return "";
675	        }
676	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
677	    }
678	}
